function notify(text,seconds=3){$('notice').textContent=text;$('notice').hidden=false;noticeEnd=gameTime+seconds;}
function stats(id=active){const g=gunStats(id,xp[id]||0);return {...g,damage:(g.damage+(paidUpgrades[id]?.damage||0))*blessings.B.attack+Object.values(blessings.B.elements).reduce((a,b)=>a+b,0),mag:Math.ceil(g.mag*blessings.B.mag)+(paidUpgrades[id]?.mag||0)};}
function gain(id,n){if(practice)return;const before=gunLevel(xp[id]||0);xp[id]=(xp[id]||0)+n;pendingXP=true;if(gunLevel(xp[id])>before)notify(GUNS[id].name+' 升級至 Lv.'+gunLevel(xp[id]),4);}
