function trace(a,b,color=0xf4d78b){if(tracers.length>25){const old=tracers.shift();scene.remove(old.mesh);old.mesh.geometry.dispose();old.mesh.material.dispose();}const dir=b.clone().sub(a),distance=dir.length();if(distance<.001)return;dir.normalize();const mesh=new THREE.Mesh(new THREE.CylinderGeometry(CFG.tracerRadius,CFG.tracerRadius,1,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.84,depthWrite:false}));mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir);mesh.position.copy(a);scene.add(mesh);tracers.push({mesh,start:a.clone(),dir,distance,travel:0,fade:0});}
