function showDamageDirection(source){if(!source)return;const toSource=source.clone().sub(P.pos).setY(0);if(toSource.lengthSq()<.001)return;toSource.normalize();const front=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw)),right=new THREE.Vector3(Math.cos(yaw),0,-Math.sin(yaw));const angle=Math.atan2(toSource.dot(right),toSource.dot(front))*180/Math.PI;$('damageDir').style.transform='translate(-50%,-50%) rotate('+angle+'deg)';$('damageDir').style.opacity='1';damageDirectionEnd=gameTime+.72;}
function damagePlayer(amount,head=false,source=null){if(mode!=='combat'||P.hp<=0||actions.invulnerable()||gameTime<reviveUntil)return;const vulnerable=P.status['雷']?.end>gameTime?1.05:1;const out=armorDamage(P.hp,P.armor,amount*vulnerable,head);P.hp=out.hp;P.armor=out.armor;hurtFlash=.75;showDamageDirection(source);if(P.hp<=0&&blessings.B.revives>0){blessings.B.revives--;P.hp=CFG.playerHP;P.status={};P.flash=0;reviveUntil=gameTime+3;notify('祝福復活 · 滿血恢復 · 3 秒免傷',3);return;}if(P.hp<=0){mode='dead';battleAudio.pauseMusic();keys.clear();fireHeld=false;hook=null;document.exitPointerLock?.();$('shop').hidden=true;$('pause').hidden=false;$('pauseTitle').textContent='防線失守';$('pauseInfo').textContent='完成 '+Math.max(0,wave-1)+' 波 · 擊倒 '+kills+' 名敵人。武器經驗已保留。';$('resume').hidden=true;save();}}
function hurtEnemy(e,damage,owner=true,gun=active,head=false,element=null){if(e.hp<=0)return;damage*=e.status['雷']?.end>gameTime?1.05:1;e.hp-=damage;e.hit=.18;if(owner)actions.number(e.pos,damage);burst(e.pos.clone().add(new THREE.Vector3(0,head?1.55:1.1,0)),0x992f37,5,1.5,.4);if(owner&&GUNS[gun])gain(gun,2);if(element)applyStatus(e,element,owner,gun);if(e.hp<=0&&practice){kills++;actions.kill();respawnPracticeEnemy(e);return;}if(e.hp<=0){e.hp=0;if(e.labelSprite)e.labelSprite.visible=false;e.deadAt=gameTime;kills++;if(owner){actions.kill();const reward=Math.round((70+e.tier*40)*difficulty);money+=reward;if(GUNS[gun])gain(gun,25+e.tier*10);notify('擊倒 '+e.label+' ＋$'+reward,1.5);}if(!e.boss&&!e.creeper)dropWeapon(e.gun,e.pos);e.model.group.rotation.z=Math.PI/2;e.model.group.position.y=.3;sound(130,.08,'triangle');}}
function sphereHit(origin,dir,pos,r,max){const oc=origin.clone().sub(pos),b=oc.dot(dir),c=oc.lengthSq()-r*r,disc=b*b-c;if(disc<0)return null;let t=-b-Math.sqrt(disc);if(t<.002)t=-b+Math.sqrt(disc);return t>.002&&t<max?t:null;}
function playerSphereHit(origin,dir,pos,r,max){const oc=origin.clone().sub(pos),d=dir.clone();oc.y/=blessings.B.height;d.y/=blessings.B.height;const a=d.lengthSq(),b=oc.dot(d),c=oc.lengthSq()-r*r,v=b*b-a*c;if(v<0)return null;let t=(-b-Math.sqrt(v))/a;if(t<.002)t=(-b+Math.sqrt(v))/a;return t>.002&&t<max?t:null;}
function targetRay(origin,dir,max=80,enemyTargets=true,includeBarrels=true){let hit=S.cast(origin,dir,max),limit=hit?.distance||max;if(enemyTargets)for(const e of enemies)if(e.hp>0){for(const [y,r,head]of [[1.55,.2,true],[1.04,.34,false],[.47,.27,false]]){const t=sphereHit(origin,dir,e.pos.clone().add(new THREE.Vector3(0,y*(e.boss?1.2:1),0)),r*(e.boss?1.2:1),limit);if(t!==null){limit=t;hit={enemy:e,head,distance:t,point:origin.clone().addScaledVector(dir,t)};}}}if(includeBarrels)for(const b of barrels)if(b.hp>0){const t=sphereHit(origin,dir,b.pos.clone().add(new THREE.Vector3(0,.42,0)),.3,limit);if(t!==null){limit=t;hit={barrel:b,distance:t,point:origin.clone().addScaledVector(dir,t)};}}const agv=tactics.getAGV();if(agv&&agv.hp>0){const t=sphereHit(origin,dir,agv.pos.clone().add(new THREE.Vector3(0,.35,0)),.40,limit);if(t!==null){hit={agv,distance:t,point:origin.clone().addScaledVector(dir,t)};}}return hit||{distance:max,point:origin.clone().addScaledVector(dir,max)};}
function forward(){return new THREE.Vector3(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch)).normalize();}
