function fire(){if(mode!=='combat'||shopOpen||actions.busy()||gameTime<lastShot||reloadEnd>0)return;const g=stats();if(!ammo[active]){reload();return;}tactics.hear(P.pos);lastShot=gameTime+g.interval;ammo[active]--;const id=active,eyeDir=new THREE.Vector3();camera.getWorldDirection(eyeDir);const eyeHit=targetRay(camera.position,eyeDir,g.range+5);const origin=muzzle(),baseDir=eyeHit.point.clone().sub(origin).normalize();const near=S.cast(P.pos.clone().add(new THREE.Vector3(0,py(crouched?.85:1.2),0)),origin.clone().sub(P.pos.clone().add(new THREE.Vector3(0,py(crouched?.85:1.2),0))).normalize(),P.pos.clone().add(new THREE.Vector3(0,py(crouched?.85:1.2),0)).distanceTo(origin));
 for(let i=0;i<g.pellets;i++){const dir=baseDir.clone().add(new THREE.Vector3((Math.random()-.5)*g.spread,(Math.random()-.5)*g.spread,(Math.random()-.5)*g.spread).multiplyScalar(aim?.45:1)).normalize(),hit=near||targetRay(origin,dir,g.range);trace(origin,hit.point);if(hit.enemy){const critical=Math.random()<g.crit;hurtEnemy(hit.enemy,g.damage*(hit.head?2:1)*(critical?1.5:1),true,id,hit.head,Math.random()<g.elementChance?g.element:null);for(const element of Object.keys(blessings.B.elements))if(Math.random()<.15)applyStatus(hit.enemy,element,true,id);$('hit').style.opacity='1';fireFlash=.15;if(critical)notify('暴擊！',.6);}else if(hit.agv){tactics.damageAGV(g.damage,'playerGun');}else if(hit.barrel){hit.barrel.hp-=g.damage;hit.barrel.lastGun=id;if(hit.barrel.hp<=0)explodeBarrel(hit.barrel,true,id);}else{destruction.hit(hit,g.damage);if(!hit.body?.destroyed)mark(hit);}}
 burst(origin,0xffdd7f,3,.4,.055);const casing=origin.clone().add(new THREE.Vector3(.12,0,.1));burst(casing,0xc9a351,1,1.2,.4);battleAudio.gun(id);pitch=clamp(pitch+g.recoil*(aim?.6:1)*(P.status['土']?.end>gameTime?1.3:1),-1.0,.85);}
function reload(){if(mode!=='combat'||actions.busy()||reloadEnd>0||ammo[active]>=stats().mag)return;reloadEnd=gameTime+stats().reload;sound(700,.08,'triangle');notify('換彈中…',stats().reload);}
function dropWeapon(id,pos){if(drops.length>=20){disposeGroup(drops.shift().mesh);}const g=gunModel(id);g.position.copy(pos).add(new THREE.Vector3(0,.23,0));g.rotation.set(0,Math.random()*6.28,Math.PI/2);scene.add(g);drops.push({id,pos:pos.clone(),mesh:g,end:gameTime+CFG.dropSeconds,ammo:Math.ceil(GUNS[id].mag*.5)});}
function disposeGroup(g){scene.remove(g);/* geometry and base materials are shared */}
function pickup(){if(tactics.supply())return;if(pickupLoot())return;if(!nearestDrop||mode!=='combat')return;const d=nearestDrop,slot=GUNS[d.id].slot,old=inventory[slot];if(old&&old!==d.id)dropWeapon(old,P.pos);inventory[slot]=d.id;ammo[d.id]=Math.min(stats(d.id).mag,d.ammo);switchGun(d.id);d.end=0;nearestDrop=null;notify('拾取 '+GUNS[d.id].name+' · 同型武器經驗保留');}
function makeBarrel(pos){const group=new THREE.Group();group.position.copy(pos);mesh(group,'cyl',0xb05439,0,.38,0,.23,.72,.23);mesh(group,'cyl',0x4a4240,0,.76,0,.08,.06,.08);for(const h of [.14,.6])mesh(group,'cyl',0x444747,0,h,0,.238,.035,.238);mesh(group,'box',0xe3ba53,0,.39,-.233,.2,.22,.012);scene.add(group);const b={pos:pos.clone(),mesh:group,hp:CFG.barrelHP,exploded:false,lastGun:'pistol'};barrels.push(b);return b;}
function explosion(pos,radius,max,owner,gun,skipPlayer=false){tactics.hear(pos,18);const agv=tactics.getAGV();if(agv&&S.clear(pos,agv.pos.clone().add(new THREE.Vector3(0,.35,0)),true))tactics.damageAGV(explosionFalloff(agv.pos.distanceTo(pos),radius,max),'explosion');if(owner)max*=blessings.B.attack;destruction.blast(pos,radius,max);burst(pos,0xffa743,24,4,.55);burst(pos,0x565451,8,1.5,1.2);battleAudio.explosion(pos.distanceTo(P.pos));if(!skipPlayer){const p=P.pos.clone().add(new THREE.Vector3(0,py(.8),0)),d=p.distanceTo(pos);if(d<radius&&S.clear(pos,p,true))damagePlayer(explosionFalloff(d,radius,max),false,pos);}for(const e of enemies)if(e.hp>0){const p=e.pos.clone().add(new THREE.Vector3(0,.8,0)),d=p.distanceTo(pos);if(d<radius&&S.clear(pos,p,true))hurtEnemy(e,explosionFalloff(d,radius,max),owner,gun);}for(const b of barrels)if(!b.exploded){const p=b.pos.clone().add(new THREE.Vector3(0,.4,0)),d=p.distanceTo(pos);if(d<radius&&S.clear(pos,p,true)){b.hp-=explosionFalloff(d,radius,max);if(b.hp<=0)explodeBarrel(b,owner,gun);}}}
function explodeBarrel(b,owner=true,gun=active,direct=false){if(b.exploded)return;b.exploded=true;b.hp=0;b.mesh.visible=false;if(direct)damagePlayer(CFG.barrelDamage,false,b.pos);explosion(b.pos.clone().add(new THREE.Vector3(0,.4,0)),CFG.barrelRadius,CFG.barrelDamage,owner,gun,direct);}
function throwItem(type){if(mode!=='combat'||actions.busy()||(type==='grenade'?grenades:flashes)<=0)return;if(type==='grenade')grenades--;else flashes--;const origin=P.pos.clone().add(new THREE.Vector3(0,py(crouched?.9:1.25),0)),dir=forward();const g=new THREE.Mesh(sphereGeo,mat(type==='grenade'?0x738251:0xc6d4d6));g.scale.setScalar(.075);g.position.copy(origin);scene.add(g);projectiles.push({type,mesh:g,pos:origin,v:dir.multiplyScalar(7).add(new THREE.Vector3(0,2.5,0)),end:gameTime+(type==='grenade'?CFG.grenadeFuse:CFG.flashFuse),gun:active});sound(400,.08,'triangle');}
function flash(pos){burst(pos,0xffffff,18,2,.2);battleAudio.flash(pos.distanceTo(P.pos));const eye=P.pos.clone().add(new THREE.Vector3(0,py(crouched?1:1.5),0)),d=eye.distanceTo(pos);if(d<CFG.flashRadius&&S.clear(pos,eye)){const facing=forward().dot(pos.clone().sub(eye).normalize()),strength=(1-d/CFG.flashRadius)*(facing>0?.9:.3);P.flash=Math.max(P.flash,5*strength);}for(const e of enemies)if(e.hp>0){const eye=e.pos.clone().add(new THREE.Vector3(0,1.5,0)),d=eye.distanceTo(pos);if(d<CFG.flashRadius&&S.clear(pos,eye)){const direction=new THREE.Vector3(-Math.sin(e.facing),0,-Math.cos(e.facing)),facing=direction.dot(pos.clone().sub(eye).normalize());tactics.forget(e);e.flash=Math.max(e.flash,(1-d/CFG.flashRadius)*(facing>0?5:1.5));}}}
function startHook(){if(mode!=='combat'||actions.busy()||hook||hookCD>0||hookLatch)return;hookLatch=true;const o=P.pos.clone().add(new THREE.Vector3(0,py(crouched?.85:1.25),0)),view=new THREE.Vector3();camera.getWorldDirection(view);const aimHit=targetRay(camera.position,view,15,false),dir=aimHit.point.clone().sub(o).normalize(),hit=targetRay(o,dir,CFG.grappleRange,false);if(hit.distance>=CFG.grappleRange&&!hit.kind&&!hit.barrel){notify('繩索未命中 · 有效距離 5m',1);return;}if(hit.barrel){explodeBarrel(hit.barrel,true,active,true);hookCD=CFG.grappleCooldown;notify('勾中瓦斯桶！承受完整爆炸傷害',2);return;}if(!hit.kind)return;const dest=hit.point.clone().addScaledVector(dir,-.36);dest.y=clamp(dest.y-(py(crouched?.85:1.25)),0,CFG.floorHeight-(py(crouched?1.15:1.72))-.02);hook={point:hit.point.clone(),dest};sound(600,.1,'triangle');}
