function safePoint(center){if(!S.blocked(center.x,0,center.z))return center.clone().setY(0);for(let r=.3;r<15;r+=.3)for(let a=0;a<6.28;a+=.3){const p=new THREE.Vector3(center.x+Math.cos(a)*r,0,center.z+Math.sin(a)*r);if(!S.blocked(p.x,0,p.z))return p;}throw Error('無安全出生點');}
function moveActor(a,dx,dy,dz,h=1.7,r=.22){let moved=false;for(const [axis,n]of [['x',dx],['z',dz],['y',dy]]){const steps=Math.ceil(Math.abs(n)/.06);for(let i=0;i<steps;i++){const old=a.pos.clone(),test=old.clone();test[axis]+=n/steps;test.y=clamp(test.y,0,CFG.floorHeight-h-.02);if(!S.blocked(test.x,test.y,test.z,r,h)){moved=moved||old.distanceToSquared(test)>1e-8;a.pos.copy(test);}else{if(axis==='y'){let lo=0,hi=1;for(let j=0;j<9;j++){const t=(lo+hi)/2,p=old.clone().lerp(test,t);if(S.blocked(p.x,p.y,p.z,r,h))hi=t;else lo=t;}a.pos.copy(old.lerp(test,lo));if(a===P)P.vy=0;}break;}}}return moved;}
function throwBossGrenade(e){const pos=e.pos.clone().add(new THREE.Vector3(0,1.85,0)),target=e.lastKnown.clone().setY(.08),time=clamp(pos.distanceTo(target)/7,.7,1.5),v=target.clone().sub(pos).multiplyScalar(1/time);v.y+=CFG.gravity*time/2;const m=new THREE.Mesh(sphereGeo,new THREE.MeshStandardMaterial({color:0xab7042,emissive:0x000000,roughness:.5}));m.scale.setScalar(.11);m.position.copy(pos);scene.add(m);projectiles.push({boss:true,type:'grenade',mesh:m,pos,v,end:gameTime+CFG.grenadeFuse,gun:null,glow:null});sound(300,.1,'triangle');}

