function makeCreeperModel(model){
 for(const child of model.group.children)child.visible=false;
 const green=0x5aa83c,dark=0x163b21;
 mesh(model.group,'box',green,0,1.48,0,.50,.50,.50);
 mesh(model.group,'box',green,0,.91,0,.36,.65,.30);
 for(const x of [-.18,.18])for(const z of [-.16,.16])mesh(model.group,'box',green,x,.28,z,.23,.50,.25);
 for(const x of [-.12,.12])mesh(model.group,'box',dark,x,1.54,-.256,.10,.10,.012);
 mesh(model.group,'box',dark,0,1.40,-.256,.10,.15,.012);
 for(const x of [-.085,.085])mesh(model.group,'box',dark,x,1.34,-.256,.07,.12,.012);
}
function clearCreepers(){
 for(let i=enemies.length-1;i>=0;i--)if(enemies[i].creeper){
  const e=enemies[i];disposeGroup(e.model.group);e.labelTexture?.dispose();e.labelSprite?.material.dispose();enemies.splice(i,1);
 }
}
function tickCreeper(e,dt){
 if(e.hp<=0||mode!=='combat')return;
 const origin=e.pos.clone().add(new THREE.Vector3(0,.9,0));
 const target=P.pos.clone().add(new THREE.Vector3(0,py(.9),0));
 if(e.fuseEnd===null){
  tactics.think(e,dt);
  if(e.flash<=0&&origin.distanceTo(target)<=CFG.creeperTriggerRadius&&S.clear(origin,target)){
   e.fuseEnd=gameTime+CFG.creeperFuse;
   notify('苦力怕即將爆炸！離開 6m 範圍或擊殺它',2);
   sound(900,.15,'triangle');
  }
 }
 if(e.fuseEnd!==null){
  e.awareness='爆炸倒數 '+Math.max(0,e.fuseEnd-gameTime).toFixed(1)+'s';
  e.model.group.scale.setScalar(1+Math.sin(gameTime*30)*.08);
  if(gameTime>=e.fuseEnd){
   e.hp=0;e.deadAt=gameTime;e.model.group.visible=false;
   burst(origin,0x96ef61,24,4,.55);burst(origin,0x565451,8,1.5,1.2);
   battleAudio.explosion(origin.distanceTo(target));
   if(P.hp>0&&origin.distanceTo(target)<=CFG.creeperBlastRadius&&S.clear(origin,target)){
    P.hp/=10;hurtFlash=.9;showDamageDirection(e.pos);
    notify('苦力怕爆炸！當前生命值降為 1/10',3);
   }
  }
 }
 e.model.group.position.copy(e.pos);
}

function spawnEnemy(creeper=false){const boss=!creeper&&!practice&&wave%3===0&&remaining===1;let options=S.candidates(P.pos.clone().setY(0),8,20).filter(p=>!S.blocked(p.x,0,p.z)&&enemies.every(e=>e.hp<=0||p.distanceTo(e.pos)>1)&&barrels.every(b=>b.exploded||p.distanceTo(b.pos)>.8));if(!options.length)options=S.candidates(P.pos.clone().setY(0),5,100).filter(p=>!S.blocked(p.x,0,p.z)&&enemies.every(e=>e.hp<=0||p.distanceTo(e.pos)>1));if(!options.length)return false;let p=options[Math.floor(Math.random()*options.length)];for(let i=0;i<10;i++){const q=options[Math.floor(Math.random()*options.length)];if(!S.clear(P.pos.clone().add(new THREE.Vector3(0,py(1.4),0)),q.clone().add(new THREE.Vector3(0,1.4,0)))){p=q;break;}}
 const tier=boss||creeper?0:wave>=4&&Math.random()<.3?2:wave>=2&&Math.random()<.4?1:0,gun=tier===2?'sniper':tier===1?'rifle':Math.random()<.5?'pistol':'smg',model=actor(true);model.setGun(gun);if(creeper)makeCreeperModel(model);if(boss){model.poseGun(false);model.weapon.visible=false;mesh(model.group,'box',0xb65d37,0,1.10,-.18,.34,.30,.045);mesh(model.group,'sphere',0xa87945,.28,1.03,-.27,.10,.10,.10);}model.group.position.copy(p);const e={pos:p.clone(),model,hp:(65+tier*35)*(1+Math.min(wave-1,15)*.1),maxHP:(65+tier*35)*(1+Math.min(wave-1,15)*.1),boss,creeper,fuseEnd:null,gun,tier,label:creeper?'苦力怕':boss?'BOSS 擲彈兵':['巡邏兵','突擊兵','精銳'][tier],cooldown:1+Math.random(),status:{},flash:0,hit:0,think:0,visible:false,deadAt:0,stuck:0,ammo:GUNS[gun].mag,reload:0};const canvas=document.createElement('canvas');canvas.width=256;canvas.height=80;const tex=new THREE.CanvasTexture(canvas);e.labelCanvas=canvas;e.labelTexture=tex;e.labelLast='';const label=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,depthTest:true,transparent:true}));label.position.set(0,1.98,0);label.scale.set(1.3,.406,1);e.model.group.add(label);e.labelSprite=label;if(boss){e.hp*=2;e.maxHP*=2;}tactics.init(e);enemies.push(e);if(!creeper)remaining--;return true;}
function tickEnemies(dt){for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];if(e.hp<=0){if(gameTime-e.deadAt>2){disposeGroup(e.model.group);e.labelTexture?.dispose();e.labelSprite?.material.dispose();enemies.splice(i,1);}continue;}const labelKey=Math.ceil(e.hp)+'|'+e.awareness+'|'+statusName(e);if(labelKey!==e.labelLast){e.labelLast=labelKey;const c=e.labelCanvas.getContext('2d');c.clearRect(0,0,256,80);c.fillStyle='#102830dd';c.fillRect(0,0,256,80);c.fillStyle='#f5dcc2';c.font='bold 23px sans-serif';c.textAlign='center';c.fillText(e.label+(e.flash>.2?' · 致盲':''),128,26);c.fillStyle='#5a3435';c.fillRect(12,37,232,10);c.fillStyle='#e88679';c.fillRect(12,37,232*clamp(e.hp/e.maxHP,0,1),10);c.fillStyle='#eecb83';c.font='18px sans-serif';c.fillText(e.awareness+' '+statusName(e),128,70);e.labelTexture.needsUpdate=true;}e.flash=Math.max(0,e.flash-dt);e.hit=Math.max(0,e.hit-dt);e.cooldown-=dt;e.think-=dt;e.reload=Math.max(0,e.reload-dt);e.model.group.scale.setScalar((e.boss?1.2:1)*(e.hit>0?.96:1));if(e.creeper){tickCreeper(e,dt);continue;}const distance=tactics.think(e,dt);
 if(e.boss){e.model.poseGun(false);if(!practice&&e.visible&&e.flash<.2&&e.cooldown<=0){throwBossGrenade(e);e.cooldown=3.8;}e.model.group.position.copy(e.pos);e.model.arms[0].rotation.x=-.4;e.model.arms[1].rotation.x=e.cooldown>3.4?-2.2:-.4;continue;}
 if(!practice&&e.visible&&e.flash<.2&&e.cooldown<=0&&e.reload<=0){if(e.ammo<=0){e.reload=GUNS[e.gun].reload;e.ammo=GUNS[e.gun].mag;}else{e.ammo--;e.cooldown=clamp(.8-.04*wave,.28,.8)/(difficulty*.8);const origin=e.pos.clone().add(new THREE.Vector3(.1,1.25,0)),target=P.pos.clone().add(new THREE.Vector3(0,py(crouched?.7:1.18),0));const spread=(.17+distance*.035)*(e.status['土']?.end>gameTime?1.3:1)/difficulty;target.add(new THREE.Vector3((Math.random()-.5)*spread,(Math.random()-.5)*spread,(Math.random()-.5)*spread));const dir=target.clone().sub(origin).normalize(),length=origin.distanceTo(target),wall=targetRay(origin,dir,length+.5,false);let t=null,head=false;for(const [height,r,isHead]of [[crouched?1:1.55,.18,true],[crouched?.6:1,.32,false]]){const n=playerSphereHit(origin,dir,P.pos.clone().add(new THREE.Vector3(0,py(height),0)),r,wall?.distance||length+.5);if(n!==null&&(t===null||n<t)){t=n;head=isHead;}}trace(origin,wall?.point||target,0xf08865);if(t===null&&wall?.agv)tactics.damageAGV(10*difficulty,'enemyGun');if(t===null&&wall?.body)destruction.hit(wall,10*difficulty);if(wall?.barrel&&t===null){wall.barrel.hp-=10*difficulty;if(wall.barrel.hp<=0)explodeBarrel(wall.barrel,false,e.gun);}if(t!==null&&Math.random()<CFG.enemyHitChance){damagePlayer((7+e.tier*3)*difficulty*(head?1.7:1),head,e.pos);if(difficulty>=1.6&&Math.random()<.18)applyStatus(P,GUNS[e.gun].element,false,e.gun,e.pos);}battleAudio.gun(e.gun,distance,.45);}}
 e.model.group.position.copy(e.pos);e.model.arms[0].rotation.x=-.7;e.model.arms[1].rotation.x=-1.1;e.model.poseGun(true,e.reload>0);}}
function tickStatuses(a,dt,isPlayer){for(const [kind,s]of Object.entries(a.status)){if(kind==='火')while(s.next<=gameTime&&s.next<=s.end){s.next+=1;if(isPlayer){if(mode!=='combat')break;damagePlayer(CFG.playerHP*.03,false,s.source);}else if(a.hp>0)hurtEnemy(a,a.maxHP*.03,s.owner,s.gun);}if(gameTime>=s.end)delete a.status[kind];}}
function clearRound(){creeperSpawned=false;tactics.clear();destruction.reset();actions.reset();clearLoot();for(const list of [enemies,barrels,drops,projectiles,particles,tracers]){for(const o of list){disposeGroup(o.mesh||o.model?.group);if(list===enemies){o.labelTexture?.dispose();o.labelSprite?.material.dispose();}if(o.glow){scene.remove(o.glow);o.glow.geometry.dispose();o.glow.material.dispose();}if(list===projectiles&&o.boss)o.mesh.material.dispose();if(list===particles)o.mesh.material.dispose();if(list===tracers){o.mesh.geometry.dispose();o.mesh.material.dispose();}}list.length=0;}for(const d of decals){scene.remove(d);d.geometry.dispose();d.material.dispose();}decals.length=0;}
const loot=[],lootKinds={heal:{name:'補血 +30',color:0x69c8a2},armor:{name:'防彈衣 +25',color:0x75a3dc},grenade:{name:'手榴彈 +1',color:0xa6b766},flash:{name:'閃光彈 +1',color:0xe3d69c},cash:{name:'金錢 +150',color:0xf0bc59}};
let selectedMachineNames=[],nearestLoot=null;
function shuffled(list){const a=list.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function clearLoot(){for(const l of loot)scene.remove(l.mesh);loot.length=0;nearestLoot=null;}
function placeLoot(o,candidates){
 const yaw=o.yaw||0,c=Math.cos(yaw),s=Math.sin(yaw),h=o.kind==='machine'?1.80:o.kind==='ground'?0:.715;
 // Put the box on the closest exposed edge, not at an unreachable cabinet centre.
 let access=null;const ordered=candidates.map(p=>({p,d:Math.hypot(p.x-o.x,p.z-o.z)})).sort((a,b)=>a.d-b.d);
 for(const {p} of ordered){if(S.clear(p.clone().setY(1.55),new THREE.Vector3(o.x,h+.2,o.z),true)){access=p;break;}}
 if(!access)access=P.pos;
 const dx=access.x-o.x,dz=access.z-o.z,lx=clamp(dx*c+dz*s,-o.w/2+.16,o.w/2-.16),lz=clamp(-dx*s+dz*c,-o.d/2+.16,o.d/2-.16);
 const pos=new THREE.Vector3(o.x+lx*c-lz*s,h+.10,o.z+lx*s+lz*c),kind=Object.keys(lootKinds)[Math.floor(Math.random()*5)],g=new THREE.Group();g.position.copy(pos);g.name='Loot_'+kind;
 mesh(g,'box',lootKinds[kind].color,0,0,0,.22,.20,.22);mesh(g,'box',0xf7f3df,0,.102,0,.055,.006,.22);mesh(g,'box',0xf7f3df,0,.103,0,.22,.006,.055);scene.add(g);loot.push({kind,pos,mesh:g,support:o.name||'貨架',supportKind:o.kind,access:access.clone()});
}
function refreshWaveLayout(){
 clearLoot();endHook();nearestDrop=null;
 for(const d of drops)scene.remove(d.mesh);drops.length=0;
 for(const d of decals){scene.remove(d);d.geometry.dispose();d.material.dispose();}decals.length=0;
 const burningNames=new Set([...destruction.burning].map(b=>b.machineName));const available=D.objects.filter(o=>o.kind==='machine'&&!destruction.exploded.has(o.name));const kept=[...available.filter(o=>burningNames.has(o.name)),...shuffled(available.filter(o=>!burningNames.has(o.name)))].slice(0,50);selectedMachineNames=kept.map(o=>o.name);
 F.setMachineSelection(selectedMachineNames);S.setMachineSelection(selectedMachineNames);destruction.resetMachines();
 if(S.blocked(P.pos.x,P.pos.y,P.pos.z)){P.pos.copy(safePoint(P.pos));P.vy=0;}
 S.flow(P.pos);
 for(const b of barrels)if(!b.exploded&&S.blocked(b.pos.x,0,b.pos.z,.3,.8)){b.pos.copy(safePoint(b.pos));b.mesh.position.copy(b.pos);}
 resizePlayer();const accessPoints=S.candidates(P.pos,0,999);
 for(const o of shuffled(kept.filter(o=>!burningNames.has(o.name))).slice(0,10))placeLoot(o,accessPoints);
 for(const o of shuffled(D.objects.filter(o=>o.kind==='rack')).slice(0,Math.round(D.objects.filter(o=>o.kind==='rack').length*.25)))placeLoot(o,accessPoints);
}
function lootInReach(l){const hand=P.pos.clone().add(new THREE.Vector3(0,py(1.3),0));return hand.distanceTo(l.pos)<1.85&&S.clear(hand,l.pos,true);}
function pickupLoot(){if(!nearestLoot||!['buy','combat'].includes(mode)||shopOpen)return false;const l=nearestLoot;if(!loot.includes(l)||!lootInReach(l))return false;
 if(l.kind==='heal'&&P.hp>=100||l.kind==='armor'&&P.armor>=armorMax()||l.kind==='grenade'&&grenades>=5||l.kind==='flash'&&flashes>=5){notify('已達上限，道具保留',1);return true;}
 if(l.kind==='heal')P.hp=Math.min(100,P.hp+30);else if(l.kind==='armor')P.armor=Math.min(armorMax(),P.armor+25);else if(l.kind==='grenade')grenades++;else if(l.kind==='flash')flashes++;else money+=150;
 scene.remove(l.mesh);loot.splice(loot.indexOf(l),1);nearestLoot=null;notify('取得 '+lootKinds[l.kind].name,1.5);return true;}
function playTimeText(){const n=Math.floor(gameTime);return [Math.floor(n/3600),Math.floor(n/60)%60,n%60].map(v=>String(v).padStart(2,'0')).join(':');}
function beginBuy(){clearCreepers();creeperSpawned=false;actions.reset();mode='buy';phaseTime=CFG.buySeconds;wave++;blessings.offer(wave);remaining=4+wave*2;refreshWaveLayout();tactics.spawnAGV();notify('第 '+wave+' 波準備 · 20 秒購買 · 保留 50 台機台',3);openShop();}
function startGame(training=false){practice=training===true;touchReset();battleAudio.unlock();battleAudio.resumeMusic();paidUpgrades={};blessings.reset();reviveUntil=0;clearRound();wave=0;kills=0;money=CFG.startMoney;gameTime=0;P.pos.copy(safePoint(new THREE.Vector3(D.spawn[0],0,D.spawn[1])));P.hp=CFG.playerHP;P.armor=0;P.fuel=100;P.vy=0;P.status={};P.flash=0;hook=null;hookCD=0;hookLatch=false;jumpLatch=false;grounded=true;keys.clear();fireHeld=false;aim=false;grenades=2;flashes=2;inventory={side:'pistol',main:null};ammo={pistol:gunStats('pistol',xp.pistol||0).mag};reloadEnd=0;lastShot=0;yaw=Math.PI;pitch=-.12;difficulty=Number($('difficulty').value);for(const d of F.doors){if(d.destroyed)continue;d.t=0;d.target=0;d.manualUntil=0;}S.flow(P.pos);const candidates=S.candidates(P.pos,4,26);for(let tries=0;tries<200&&barrels.length<CFG.barrelCount;tries++){const p=candidates[Math.floor(Math.random()*candidates.length)];if(p&&!S.blocked(p.x,0,p.z,.34,.8)&&barrels.every(b=>b.pos.distanceTo(p)>2.3))makeBarrel(p);}switchGun('pistol');$('menu').hidden=true;$('pause').hidden=true;$('resume').hidden=false;if(practice){wave=1;remaining=5;phaseTime=0;refreshWaveLayout();mode='combat';closeShop(false);for(let i=0;i<5;i++)spawnEnemy();notify('射擊練習場 · 五名移動敵人 · 擊倒立即重生',4);requestLock();}else beginBuy();$('leavePractice').hidden=!practice;$('shopBtn').hidden=practice;avatar.group.visible=true;updateCamera(1);updateHUD();}

function respawnPracticeEnemy(e){
 const old=e.pos.clone();
 const points=S.candidates(P.pos.clone().setY(0),0,999).filter(p=>p.distanceTo(P.pos)>3&&p.distanceTo(old)>2&&!S.blocked(p.x,0,p.z,.22,1.7)&&enemies.every(other=>other===e||other.hp<=0||p.distanceTo(other.pos)>1)&&barrels.every(b=>b.exploded||p.distanceTo(b.pos)>.8));
 // The previous valid spawn remains a fallback if the entire navigation region is obstructed.
 e.pos.copy(points.length?points[Math.floor(Math.random()*points.length)]:safePoint(old));
 e.hp=e.maxHP;e.status={};e.flash=0;e.hit=0;e.deadAt=0;e.stuck=0;e.reload=0;e.ammo=GUNS[e.gun].mag;e.cooldown=1;e.labelLast='';e.labelSprite.visible=true;e.model.group.rotation.z=0;e.model.group.position.copy(e.pos);tactics.init(e);
}
function leaveToMenu(){mode='menu';practice=false;touchReset();keys.clear();fireHeld=false;aim=false;reloadEnd=0;endHook();shopOpen=false;nearestDrop=null;nearestDoor=null;battleAudio.pauseMusic();clearRound();save();$('shop').hidden=true;$('pause').hidden=true;$('leavePractice').hidden=true;$('shopBtn').hidden=false;$('touchControls').hidden=true;$('menu').hidden=false;document.exitPointerLock?.();updateHUD();}

function shopItem(key){if(mode!=='buy'||phaseTime<=0)return;let price=0;if(GUNS[key])price=GUNS[key].price;else price=CFG.shopPrices[key];if(price===undefined||money<price){notify('金錢不足');return;}if(key==='armor'&&P.armor>=armorMax()||key==='heal'&&P.hp>=100||key==='grenade'&&grenades>=5||key==='flash'&&flashes>=5){notify('已達上限');return;}money-=price;if(GUNS[key]){inventory[GUNS[key].slot]=key;ammo[key]=stats(key).mag;switchGun(key);}else if(key==='armor')P.armor=armorMax();else if(key==='heal')P.hp=Math.min(100,P.hp+50);else if(key==='grenade')grenades++;else if(key==='flash')flashes++;renderShop();sound(800,.08,'sine');}
function renderShop(){renderUpgrades();blessings.render($('blessingShop'));const items=$('shopItems');items.replaceChildren();const list=[...Object.keys(GUNS).filter(k=>k!=='pistol'),'armor','grenade','flash','heal'];for(const key of list){const g=GUNS[key],s=g?stats(key):null,price=g?g.price:CFG.shopPrices[key],el=document.createElement('div');el.className='item';const name=g?g.name:{armor:'防彈衣 · 補滿'+armorMax(),grenade:'手榴彈 ＋1',flash:'閃光彈 ＋1',heal:'醫療補給 ＋50 HP'}[key];el.innerHTML='<b>'+name+'</b><div class="muted">'+(g?'Lv.'+s.level+' · 傷害 '+s.damage.toFixed(0)+' · 彈匣 '+s.mag+'<br>Lv.3 解鎖 '+g.element+' 屬性':key==='armor'?'身體減傷45%，頭部不受保護':key==='heal'?'生命上限100':'最多攜帶5枚')+'</div>';const b=document.createElement('button');b.textContent='$'+price+' 購買';b.disabled=money<price||(g&&inventory.main===key);b.onclick=()=>shopItem(key);el.append(b);items.append(el);}$('shopMoney').textContent='持有 $'+money;}
function upgradeWeapon(id,kind){if(mode!=='buy'||phaseTime<=0||!GUNS[id]||!equipped(id)||!['damage','mag'].includes(kind))return false;const price=kind==='damage'?100:500;if(money<price){notify('金錢不足');return false;}const u=paidUpgrades[id]||(paidUpgrades[id]={damage:0,mag:0});money-=price;const value=kind==='damage'?1:id==='sniper'?1:5;u[kind]+=value;notify(GUNS[id].name+(kind==='damage'?' 攻擊力 +':' 彈匣容量 +')+value,2);renderShop();updateHUD();return true;}
function renderUpgrades(){const root=$('upgradeShop');root.replaceChildren();const title=document.createElement('h3');title.textContent='付費武器強化 · 本局持續';root.append(title);for(const id of [inventory.side,inventory.main].filter(Boolean)){const g=stats(id),u=paidUpgrades[id]||{damage:0,mag:0},row=document.createElement('div');row.className='item';const label=document.createElement('b');label.textContent=GUNS[id].name+' · 傷害 '+g.damage.toFixed(1)+' · 彈匣 '+g.mag;row.append(label);const note=document.createElement('p');note.className='muted';note.textContent='已強化：攻擊 +'+u.damage+'／彈匣 +'+u.mag+'。擴充後換彈裝滿；同型槍保留強化。';row.append(note);for(const kind of ['damage','mag']){const button=document.createElement('button');button.textContent=kind==='damage'?'$100 · 攻擊 +1':'$500 · 彈匣 +'+(id==='sniper'?1:5);button.disabled=money<(kind==='damage'?100:500);button.onclick=()=>upgradeWeapon(id,kind);row.append(button);}root.append(row);}}
function openShop(){touchReset();if(mode!=='buy'){notify('只能在每波開始前購買');return;}shopOpen=true;keys.clear();fireHeld=false;aim=false;document.exitPointerLock?.();$('shop').hidden=false;renderShop();}
