function radar(){const c=$('radar').getContext('2d'),size=180,k=5;c.clearRect(0,0,size,size);c.fillStyle='#152d37';c.fillRect(0,0,size,size);c.save();c.translate(90,90);c.strokeStyle='#86a49e';c.lineWidth=1;for(const w of D.walls){c.beginPath();w.outer.forEach(([x,z],i)=>{const a=(x-P.pos.x)*k,b=(z-P.pos.z)*k;i?c.lineTo(a,b):c.moveTo(a,b)});c.closePath();c.stroke();}for(const e of enemies)if(e.hp>0){c.fillStyle=e.tier===2?'#ffc45f':'#e78e80';c.beginPath();c.arc((e.pos.x-P.pos.x)*k,(e.pos.z-P.pos.z)*k,3,0,6.28);c.fill();}for(const b of barrels)if(!b.exploded){c.fillStyle='#bc7b4a';c.fillRect((b.pos.x-P.pos.x)*k-2,(b.pos.z-P.pos.z)*k-2,4,4);}c.rotate(-yaw);c.fillStyle='#a1f2d1';c.beginPath();c.moveTo(0,-7);c.lineTo(5,5);c.lineTo(-5,5);c.fill();c.restore();}
